[
  {
    "statement": "Studies evaluating peatland vegetation introduction have observed several effects.",
    "citations": []
  },
  {
    "statement": "Adding Sphagnum moss or moss fragments to peatland surfaces resulted in Sphagnum moss being present after 1 to 4 growing seasons in at least some plots.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "The cover of Sphagnum moss in plots where it was added ranged from negligible to over 90%.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "Six controlled studies found that Sphagnum cover or abundance was higher in sown plots than in unsown plots.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "Other mosses or bryophytes were present after 2 to 3 growing seasons in plots sown with moss fragments.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "The cover of other mosses or bryophytes in plots sown with moss fragments ranged from negligible to 76%.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "The cover of other mosses or bryophytes was low (less than 1%) unless the plots were mulched, shaded, or limed.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "Spreading mixed vegetation onto peatland surfaces resulted in Sphagnum moss being present after 1 to 6 growing seasons.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "The cover of Sphagnum moss after spreading mixed vegetation ranged from less than 1% to 73%.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "Six controlled studies found Sphagnum cover was higher in plots where mixed vegetation was sown than in unsown plots.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "Five studies reported Sphagnum cover was very low (less than 1%) unless plots were mulched after spreading fragments.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "Other mosses or bryophytes appeared after 1 to 6 growing seasons with cover ranging from less than 1% to 65%.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "Vascular plants appeared following the addition of mixed vegetation fragments.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "One controlled study found vascular plant cover was significantly higher in sown plots than in unsown plots.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "Another controlled study found no effect on herb cover from adding mixed vegetation fragments.",
    "citations": [
      "1822"
    ]
  },
  {
    "statement": "One study in freshwater wetlands reported a 12% overall survival of planted unrooted tree cuttings over two years.",
    "citations": [
      "3262"
    ]
  },
  {
    "statement": "The introduction of nurse plants showed no effect on the survival of planted peat swamp tree seedlings after 2 to 3 years.",
    "citations": [
      "1830"
    ]
  },
  {
    "statement": "The introduction of nurse plants showed no effect on the cover of other planted vegetation after 2 to 3 years.",
    "citations": [
      "1830"
    ]
  }
